			FunctionRegistry.getInstance().add(function);
			try {
				assertThat(GraphExplorerNativeVariantsTest
						.repeatable(parsed("SELECT (<urn:fixture-policy-test>() AS ?v) WHERE {}"))).isFalse();
			} finally {
				FunctionRegistry.getInstance().remove(function);
			}
